function checkProgress(){if(!alive('blue').length){finish(false);return}if(phase==='marching'){const frontline=Math.max(...alive('blue').map(u=>u.x)),anchor=mode==='arena'?1700:WORLD.camps[encounter-1];if(anchor-frontline<930){units.filter(u=>u.team==='red'&&u.camp===encounter-1&&u.hp>0).forEach(u=>u.active=true);phase='fighting';banner('第 '+encounter+' 處營地接戰','ENEMY CAMP');log('敵方營地已發現小隊，準備接戰。');renderBattle()}}if(phase==='fighting'&&!alive('red').some(u=>u.active&&u.camp===encounter-1)){campCleared[encounter-1]=true;if(mode==='arena'||encounter===3){finish(true);return}phase='between';betweenWait=1.6;banner('營地已清除 · 繼續推進','CAMP CLEARED');log('小隊守住陣形，繼續前往下一處營地。');renderBattle()}}
function finish(win){if(['victory','defeat'].includes(phase))return;phase=win?'victory':'defeat';selectedSkill=null;$('#targetLabel').classList.add('hidden');let reward=0,stars=alive('blue').length===5?3:alive('blue').length>=3?2:1;if(win&&mode==='adventure'&&!rewardGranted){reward=180+stage*35+(save.stars[stage-1]===0?80:0);save.coins+=reward;save.stars[stage-1]=Math.max(save.stars[stage-1],stars);save.unlocked=Math.max(save.unlocked,Math.min(12,stage+1));rewardGranted=true;persist()}$('#result').classList.remove('hidden');$('#result').innerHTML='<div class="stars">'+(win?'✦'.repeat(stars):'⚔')+'</div><h2>'+(win?'林道已被小隊突破':'小隊暫時撤退')+'</h2><p>'+(mode==='arena'?'即時五對五試煉結束':stages[stage-1]+' · 清除 '+campCleared.filter(Boolean).length+' / 3 處營地')+' · '+formatTime(elapsed)+'</p>'+(reward?'<div class="result-reward">◈ +'+reward+'</div>':'')+'<div class="result-actions"><button class="primary" id="resultPrimary">'+(win&&mode==='adventure'&&stage<12?'下一關 →':'重新挑戰')+'</button><button class="secondary" id="resultFormation">調整陣容</button></div>';$('#resultPrimary').onclick=()=>{if(win&&mode==='adventure'&&stage<12)stage++;prepare();beginBattle()};$('#resultFormation').onclick=()=>{prepare();$('#roster').scrollIntoView({behavior:'smooth',block:'start'})};log(win?'小隊取得勝利！':'小隊暫時撤退。可調整陣容與守護配置後再挑戰。');renderAll()}
