function updateCamera(dt){camera.focusTime=Math.max(0,camera.focusTime-dt);if(!camera.follow)return;const blue=alive('blue');if(!blue.length)return;let focus=camera.focusTime>0?units.find(u=>u.uid===camera.focusUid&&u.hp>0):null;let center;if(focus)center=focus.x;else{const front=Math.max(...blue.map(u=>u.x)),back=Math.min(...blue.map(u=>u.x)),red=alive('red').filter(u=>u.active&&Math.abs(u.x-front)<850);center=red.length?(Math.min(front,...red.map(u=>u.x))+Math.max(front,...red.map(u=>u.x)))/2:(front+back)/2+160;if(front-back>950)center=front-160}const goal=clamp(center-WORLD.view/2,0,WORLD.width-WORLD.view);camera.x+= (goal-camera.x)*(1-Math.exp(-dt*3))}
function step(dt){clock+=dt;toastLife-=dt;if(toastLife<=0)$('#toast').style.opacity=0;bannerLife-=dt;if(bannerLife<=0)$('#skillBanner').classList.add('hidden');effects.forEach(e=>e.life-=dt);effects=effects.filter(e=>e.life>0);floats.forEach(e=>e.life-=dt);floats=floats.filter(e=>e.life>0);updateCamera(dt);if(paused||!isBusy()){hudTime+=dt;if(hudTime>.15){updateLiveHUD();hudTime=0}return}elapsed+=dt;if(phase==='between'){betweenWait-=dt;if(betweenWait<=0){encounter++;alive('blue').forEach(u=>{heal(u,u.maxHp*.12);u.energy=clamp(u.energy+10,0,100)});phase='marching';renderBattle()}}for(const u of units){u.attackAnim=Math.max(0,u.attackAnim-dt);advanceSkillMotion(u,dt);u.walking=Math.max(0,u.walking-dt);u.hit=Math.max(0,u.hit-dt);u.death=Math.max(0,u.death-dt);if(u.hp<=0||!u.active)continue;u.cooldowns=u.cooldowns.map(n=>Math.max(0,n-dt));u.attackTimer=Math.max(0,u.attackTimer-dt);u.castLock=Math.max(0,u.castLock-dt);for(const key of Object.keys(u.statuses)){u.statuses[key]-=dt;if(u.statuses[key]<=0)delete u.statuses[key]}u.dotTimer-=dt;if(u.dotTimer<=0){u.dotTimer=1;if(u.statuses.burn)hurt(u,u.maxHp*.018,null,'火',true);if(u.statuses.poison)hurt(u,u.maxHp*.022,null,'毒',true)}if(u.statuses.bladeFury){u.spinTick=(u.spinTick||0)-dt;if(u.spinTick<=0){u.spinTick=.4;activeEnemies(u).filter(v=>distance(u,v)<185).forEach(v=>hurt(v,u.attack*.16,u,'風',true));ring(u,'#a5d9c2',80)}}if(u.statuses.healingWard){u.wardTick=(u.wardTick||0)-dt;if(u.wardTick<=0){u.wardTick=1;alive(u.team).filter(v=>distance(v,u)<350).forEach(v=>heal(v,v.maxHp*.027));ring(u,'#a7d99c',90)}}if(u.hp<=0)continue;updateMotion(u,dt);if(phase!=='between')aiMovement(u,dt)}separateUnits(dt);checkProgress();hudTime+=dt;if(hudTime>.15){updateLiveHUD();hudTime=0}}
function selectSkill(index){if(!actor||actor.hp<=0||!isBusy()||paused)return;if(!skillAvailable(actor,index)){notify(index===3&&actor.energy<100?'大招需要 100 能量':'技能正在冷卻或角色受到控制');return}const skill=liveSkill(actor.id,index);if(requiresTarget(skill)){if(!targetsFor(actor,skill).length){notify('附近沒有可指定的目標，請靠近敵軍');return}selectedSkill=index;$('#targetLabel').textContent='選擇「'+skill.name+'」的目標；超出射程時會先接近';$('#targetLabel').classList.remove('hidden');renderBattle()}else prepareCast(actor,index,null,true)}
