const walkPreview={x:42,face:1,phase:0,playing:true};
function drawWalkPreview(dt){
  const canvas=document.getElementById('walkPreview');
  if(!canvas)return;
  const c=canvas.getContext('2d'),id=catalog,sheet=walkSheets[id];
  c.clearRect(0,0,240,150);
  c.fillStyle='#a5bb9a';c.fillRect(0,128,240,1);
  c.fillStyle='#8aa78480';c.fillRect(12,131,216,2);
  if(walkPreview.playing){
    let distance=HERO_MOVE_SPEED[id]*dt*.34;
    while(distance>0){const remaining=walkPreview.face>0?198-walkPreview.x:walkPreview.x-42;const moved=Math.min(distance,Math.max(0,remaining));walkPreview.x+=walkPreview.face*moved;walkPreview.phase+=moved*4/HERO_STRIDE[id];distance-=moved;if(remaining<=moved+.0001)walkPreview.face*=-1;else break}
  }
  c.fillStyle='#172d2455';c.beginPath();c.ellipse(walkPreview.x,127,26,5,0,0,Math.PI*2);c.fill();
  if(!sheet.complete||!sheet.naturalWidth)return;
  const frame=Math.floor(walkPreview.phase)%4;
  const side=112/WALK_HEIGHT_RATIO[id];
  c.save();c.translate(walkPreview.x,128);if(walkPreview.face<0)c.scale(-1,1);
  c.drawImage(sheet,(frame%2)*512,Math.floor(frame/2)*512,512,512,-side/2,-side*506/512,side,side);
  c.restore();
}
