  if(usingExtra){const frame=Math.min((extra.frames||8)-1,Math.floor(skillPreview.elapsed/spec.duration*(extra.frames||8))),atlas=extra.sheets[Math.floor(frame/4)],cell=frame%4,side=105/extra.ratios[Math.floor(frame/4)];c.drawImage(atlas,(cell%2)*512,Math.floor(cell/2)*512,512,512,-side/2,-side*506/512,side,side)}
